        {
            if(!CanInstall(kind,cell,out reason))return null;var s=Data.Towers[kind];var t=new TowerState{Id=nextTower++,Kind=kind,Position=cell,Spent=s.Cost,Stats=new CombatStats{Damage=s.Damage,Rate=s.Rate,Range=s.Range,ProjectileSpeed=s.ProjectileSpeed,BuffDamage=s.BuffDamage}};Crystals-=s.Cost;Towers.Add(t);LastMessage="포탑 설치";return t;
        }
        public bool DestroyTower(int id) {if(Phase==SessionPhase.Augmentation)return false;var t=Towers.FirstOrDefault(x=>x.Id==id);if(t==null)return false;Towers.Remove(t);int refund=t.Spent/2;Crystals+=refund;LastMessage="철거 +"+refund+" 수정";return true;}
        UpgradeSpec FindUpgrade(string target,string stat) {return Data.Upgrades.FirstOrDefault(u=>u.Target==target&&u.Stat==stat);}
        static int Step(CombatStats s,string stat) {int n;return s.UpgradeSteps.TryGetValue(stat,out n)?n:0;}
        public int PlayerUpgradePrice(string stat) {return FindUpgrade("Player",stat)==null?-1:Data.PlayerUpgradePrice(Step(Player,stat)+1);}
        public int TowerUpgradePrice(int id,string stat) {var t=Towers.FirstOrDefault(x=>x.Id==id);if(t==null)return -1;var u=FindUpgrade(t.Kind.ToString(),stat);return u==null?-1:u.Cost+u.CostIncrement*Step(t.Stats,stat);}
        public bool UpgradePlayer(string stat,out string reason) {var u=FindUpgrade("Player",stat);reason=null;if(u==null)reason="강화 불가";else if(Phase!=SessionPhase.Preparation&&Phase!=SessionPhase.Combat)reason="현재 단계에서 강화 불가";else if(Gold<PlayerUpgradePrice(stat))reason="골드 부족";if(reason!=null)return false;Gold-=PlayerUpgradePrice(stat);Player.Add(stat,u.Delta);Player.UpgradeSteps[stat]=Step(Player,stat)+1;LastMessage="기술병 강화";return true;}
        public bool UpgradeTower(int id,string stat,out string reason) {var t=Towers.FirstOrDefault(x=>x.Id==id);var u=t==null?null:FindUpgrade(t.Kind.ToString(),stat);reason=null;if(Phase!=SessionPhase.Preparation)reason="준비 시간에만 강화 가능";else if(u==null)reason="강화 불가";else if(Crystals<TowerUpgradePrice(id,stat))reason="수정 부족";if(reason!=null)return false;int cost=TowerUpgradePrice(id,stat);Crystals-=cost;t.Spent+=cost;t.Stats.Add(stat,u.Delta);t.Stats.UpgradeSteps[stat]=Step(t.Stats,stat)+1;LastMessage="포탑 강화";return true;}
        public bool StartCombat()
        {
            if(Phase!=SessionPhase.Preparation||path.Count<2)return false;
            Phase=SessionPhase.Combat;PreparationRemaining=0;waveTime=0;spawned.Clear();DamageTotals.Clear();
            BossKilled=false;coreDamagedThisRound=false;
            playerTarget=null;playerAcquired=false;playerCooldown=0;
            foreach(var tower in Towers){tower.Target=null;tower.AcquiredOnce=false;tower.Cooldown=0;}
            LastMessage=Diagnostic?"역할 검증 전투 시작":Wave+"라운드 전투 시작";return true;
        }
        public void StartDiagnosticEncounter()
        {
            if(path.Count<2)throw new InvalidOperationException("Board missing");Diagnostic=true;Wave=1;CompletedWave=0;LastCompletionReward=0;waveTime=0;spawned.Clear();DamageTotals.Clear();Enemies.Clear();Projectiles.Clear();Towers.Clear();Gold=Data.DiagnosticGold;Crystals=Data.DiagnosticCrystals;CoreEnergy=Data.CoreEnergy;Phase=SessionPhase.Preparation;PreparationRemaining=Data.PreparationSeconds;playerTarget=null;playerAcquired=false;playerCooldown=0;Player=Data.Player.Clone();LastMessage="역할 검증 모드: 준비 후 시작";
            CoreMaximum=Data.CoreEnergy;Augments=new AugmentationEffects();BossKilled=false;choices=Array.Empty<AugmentationCard>();AugmentationRemaining=0;coreDamagedThisRound=false;
        }
        public EnemyState DebugSpawn(EnemyKind kind,float distance=0) {if(path.Count<2)throw new InvalidOperationException("Board missing");var spec=Data.Enemies[kind];var e=new EnemyState{Id=nextEnemy++,Kind=kind,Spec=spec,Health=spec.Health,PathTravelled=Mathf.Clamp(distance,0,pathLength)};PositionEnemy(e);Enemies.Add(e);return e;}
        void PositionEnemy(EnemyState e) {float d=e.PathTravelled;for(int i=0;i<lengths.Count;i++) {if(d<=lengths[i]){e.Position=Vector2.Lerp(path[i],path[i+1],d/lengths[i]);e.PathRemaining=Mathf.Max(0,pathLength-e.PathTravelled);return;}d-=lengths[i];}e.Position=path[path.Count-1];e.PathRemaining=0;}
        public void Tick(float dt,Vector2 playerPosition)
        {
            if(float.IsNaN(dt)||float.IsInfinity(dt)||dt<0)throw new ArgumentException("Invalid dt");while(dt>0) {float step=Mathf.Min(dt,.05f);StepTick(step,playerPosition);dt-=step;}
        }
        void StepTick(float dt,Vector2 playerPosition)
        {
            if(Phase==SessionPhase.Augmentation){AugmentationRemaining=Mathf.Max(0,AugmentationRemaining-dt);if(AugmentationRemaining<=.0001f)ChooseAugmentation(AugmentationDeck.BestIndex(choices));return;}
            if(Phase==SessionPhase.Preparation) {PreparationRemaining=Mathf.Max(0,PreparationRemaining-dt);if(PreparationRemaining<=0)StartCombat();return;}if(Phase!=SessionPhase.Combat)return;
            var rows=Data.Waves.Where(x=>x.Wave==Wave).ToArray();
            if(Diagnostic) {if(waveTime==0) {float diagnosticDistance=Mathf.Min(Data.DiagnosticStartDistance,pathLength*.2f);DebugSpawn(EnemyKind.Attack,diagnosticDistance);DebugSpawn(EnemyKind.Defense,diagnosticDistance+Data.DiagnosticSpacing);DebugSpawn(EnemyKind.Buff,diagnosticDistance+2*Data.DiagnosticSpacing);} }
            else foreach(var row in rows) {int count;spawned.TryGetValue(row,out count);while(count<row.Count&&waveTime+.00001f>=row.Start+count*row.Interval) {DebugSpawn(row.Kind);count++;}spawned[row]=count;}
            waveTime+=dt;
            // Calculate all auras before moving anyone so source order cannot alter the radius test.
            var boosts=Enemies.Where(e=>e.Alive).ToDictionary(e=>e,e=>Enemies.Where(other=>other!=e&&other.Alive&&other.Kind==EnemyKind.Buff&&Vector2.Distance(e.Position,other.Position)<=other.Spec.BuffRadius).Select(other=>other.Spec.BuffSpeed).DefaultIfEmpty(0).Max()); foreach(var e in boosts.Keys) e.Buffed=boosts[e]>0;
            foreach(var e in Enemies.Where(e=>e.Alive).ToArray()) {float boost=boosts[e];e.PathTravelled=Mathf.Min(pathLength,e.PathTravelled+e.MovementSpeed*(1+boost/100f)*dt);e.SlowRemaining=Mathf.Max(0,e.SlowRemaining-dt);PositionEnemy(e);if(e.PathRemaining<=.00001f){e.Exited=true;coreDamagedThisRound|=e.Spec.CoreDamage>0;CoreEnergy=Mathf.Max(0,CoreEnergy-e.Spec.CoreDamage);LastMessage="코어 -"+e.Spec.CoreDamage;}}
            if(CoreEnergy<=0) {Phase=SessionPhase.Defeat;Projectiles.Clear();LastMessage="방어 실패";return;}
            Shoot(playerPosition,Player,"Player",0,ref playerCooldown,ref playerTarget,ref playerAcquired,dt,false);
            foreach(var t in Towers.ToArray()) {if(t.Kind==TowerKind.Support)continue;float buff=Augments.TowerBuffPercent+Towers.Where(s=>s.Kind==TowerKind.Support&&Vector2.Distance(s.Position,t.Position)<=s.Stats.Range).Sum(s=>s.Stats.BuffDamage);Shoot(t.Position,t.Stats,"Tower:"+t.Id,buff,ref t.Cooldown,ref t.Target,ref t.AcquiredOnce,dt,t.Kind==TowerKind.Multi);}
            foreach(var p in Projectiles.ToArray()) {if(!p.Target.Alive){Projectiles.Remove(p);continue;}p.Position=Vector2.MoveTowards(p.Position,p.Target.Position,p.Speed*dt);if(Vector2.Distance(p.Position,p.Target.Position)<=.00001f){ApplyDamage(p.Target,p.Damage,p.Source);Projectiles.Remove(p);}}
            Enemies.RemoveAll(e=>!e.Alive);
            bool complete=Diagnostic||rows.Length>0&&rows.All(r=>spawned.ContainsKey(r)&&spawned[r]>=r.Count);
            if(complete&&Enemies.Count==0)CompleteRound();
        }
        void CompleteRound()
        {
            Projectiles.Clear();
            if(Diagnostic){Phase=SessionPhase.Victory;LastMessage="역할 검증 종료";return;}
            CompletedWave=Wave;LastCompletionReward=Data.RewardForWave(Wave);Crystals+=LastCompletionReward;
            if(!coreDamagedThisRound){Gold+=Augments.FlawlessGold;Crystals+=Augments.FlawlessCrystals;}
            LastMessage=CompletedWave+"라운드 완료 +"+LastCompletionReward+" 수정";
            if(Wave>=LastWave){Phase=SessionPhase.Victory;LastMessage+=" · 1~"+LastWave+"라운드 검증 완료";return;}
            if(!Data.Waves.Any(row=>row.Wave==Wave+1))throw new InvalidOperationException("Next wave is missing");
            Wave++;PreparationRemaining=Data.PreparationSeconds;
            if(CompletedWave%10==0&&CompletedWave<100&&BossKilled){choices=AugmentationDeck.Draw(augmentationRandom,Augments.Selected);AugmentationRemaining=30;Phase=SessionPhase.Augmentation;LastMessage+=" · 증강 선택";return;}
            Phase=SessionPhase.Preparation;
            LastMessage+=" · "+Wave+"라운드 준비";
        }
        public bool ChooseAugmentation(int index)
        {
            if(Phase!=SessionPhase.Augmentation||index<0||index>=choices.Length)return false;
            var card=choices[index];var grant=Augments.Apply(card);
            Gold+=grant.Gold;Crystals+=grant.Crystals;CoreMaximum+=grant.Core;CoreEnergy+=grant.Core;Player.Damage+=grant.PlayerDamage;
            choices=Array.Empty<AugmentationCard>();AugmentationRemaining=0;Phase=SessionPhase.Preparation;PreparationRemaining=Data.PreparationSeconds;
            LastMessage=card.GradeName+" · "+card.Title+" 선택 · "+Wave+"라운드 준비";return true;
        }
        void Shoot(Vector2 position,CombatStats stats,string source,float buff,ref float cooldown,ref EnemyState target,ref bool acquired,float dt,bool multi)
        {
            var available=Enemies.Where(e=>e.Alive&&Vector2.Distance(e.Position,position)<=stats.Range).ToArray();
            if(target!=null&&(!target.Alive||Vector2.Distance(target.Position,position)>stats.Range))target=null;
            if(target==null&&available.Length>0) {target=acquired?CombatRules.Priority(available):available.OrderBy(e=>e.Id).First();acquired=true;}
            cooldown-=dt;if(available.Length==0||stats.Rate<=0){cooldown=Mathf.Max(0,cooldown);return;}if(cooldown>0)return;
            var targets=multi?available.OrderBy(e=>e.Kind==EnemyKind.Defense?0:e.Kind==EnemyKind.Buff?1:2).ThenBy(e=>e.Health).ThenBy(e=>e.PathRemaining).ThenBy(e=>e.Id).Take(3).ToArray():new[]{target};
            while(cooldown<=.00001f) {foreach(var e in targets) {if(e==null)continue;int shots=source=="Player"?1+Augments.ExtraPlayerProjectiles:1;for(int shot=0;shot<shots;shot++)Projectiles.Add(new ProjectileState{Id=nextProjectile++,Position=position,Target=e,Source=source,Damage=stats.Damage*(1+buff/100f),Speed=stats.ProjectileSpeed});}float nextCooldown=cooldown+1/stats.Rate;if(nextCooldown<=cooldown)throw new InvalidOperationException("Attack rate exceeds floating-point timing precision");cooldown=nextCooldown;}
        }
        public int ApplyDamage(EnemyState target,float damage,string source)
        {
            if(target==null||!target.Alive)return 0;int actual=Math.Min(target.Health,CombatRules.Damage(damage,target.Spec.Defense));target.Health-=actual;int previous;DamageTotals.TryGetValue(source,out previous);DamageTotals[source]=previous+actual;if(actual>0&&source=="Player"&&Augments.PlayerSlow)target.SlowRemaining=1;if(target.Health==0){Gold+=target.Spec.Gold;if(target.Kind==EnemyKind.Boss)BossKilled=true;LastMessage="+"+target.Spec.Gold+" 골드";}if(actual>0)DamageApplied?.Invoke(target,actual);return actual;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using UnityEngine;

namespace CoreGuardian
{
    public enum EnemyKind { Attack, Defense, Buff, Boss }
    public enum TowerKind { Single, Multi, Support }
    public enum SessionPhase { Preparation, Combat, Victory, Defeat, Augmentation }
    public sealed class EnemySpec { public EnemyKind Kind; public int Health, CoreDamage, Gold; public float Speed, Defense, BuffRadius, BuffSpeed; }
    public sealed class TowerSpec { public TowerKind Kind; public int Cost; public float Damage, Rate, Range, ProjectileSpeed, BuffDamage; }
    public sealed class UpgradeSpec { public string Target, Stat; public float Delta; public int Cost, CostIncrement; }
    public sealed class WaveSpec { public int Wave, Count; public EnemyKind Kind; public float Interval, Start; }
    public sealed class CombatStats
    {
        public float Damage, Rate, Range, ProjectileSpeed, BuffDamage;
        public readonly Dictionary<string,int> UpgradeSteps = new Dictionary<string,int>();
        public CombatStats Clone() { return new CombatStats { Damage=Damage,Rate=Rate,Range=Range,ProjectileSpeed=ProjectileSpeed,BuffDamage=BuffDamage }; }
        public void Add(string stat,float value) { switch(stat) { case "damage": Damage+=value;break;case "rate":Rate+=value;break;case "range":Range+=value;break;case "projectileSpeed":ProjectileSpeed+=value;break;case "buffDamage":BuffDamage+=value;break;default:throw new ArgumentException("Unknown stat: "+stat); } }
    }
    public sealed class CombatData
    {
        public readonly Dictionary<EnemyKind,EnemySpec> Enemies = new Dictionary<EnemyKind,EnemySpec>();
        public readonly Dictionary<TowerKind,TowerSpec> Towers = new Dictionary<TowerKind,TowerSpec>();
        public readonly List<UpgradeSpec> Upgrades = new List<UpgradeSpec>();
        public readonly List<WaveSpec> Waves = new List<WaveSpec>();
        public readonly Dictionary<int,int> WaveRewards = new Dictionary<int,int>();
        public int RewardForWave(int wave) => WaveRewards.TryGetValue(wave,out var reward)?reward:WaveReward;
        public int CoreEnergy, StartGold, StartCrystals, WaveReward, PlayerFirstCost, PlayerSecondIncrease, PlayerIncreaseStep, DiagnosticGold, DiagnosticCrystals;
        public float PreparationSeconds, DiagnosticStartDistance, DiagnosticSpacing;
        public CombatStats Player;
        static float F(string s) { float v; if(!float.TryParse(s,NumberStyles.Float,CultureInfo.InvariantCulture,out v)||float.IsNaN(v)||float.IsInfinity(v)||v<0) throw new ArgumentException("Invalid non-negative number: "+s);return v; }
        static int I(string s) { float f=F(s);if(f!=Mathf.Floor(f))throw new ArgumentException("Expected integer: "+s);return (int)f; }
        static IEnumerable<string[]> Rows(string text,int columns)
        {
            var lines=text.Replace("\r","").Split('\n').Where(x=>!string.IsNullOrWhiteSpace(x)&&!x.TrimStart().StartsWith("#")).ToArray();
            if(lines.Length<2)throw new ArgumentException("CSV has no data rows");
            var ids=new HashSet<string>(); foreach(var l in lines.Skip(1)) { var r=l.Split(',').Select(x=>x.Trim()).ToArray();if(r.Length!=columns||r.Any(x=>x.Length==0)||!ids.Add(r[0]))throw new ArgumentException("Invalid/duplicate CSV row: "+l);yield return r; }
        }
        static T Kind<T>(string value) where T:struct
        {
            T result;
            if(!Enum.TryParse<T>(value,true,out result)||!Enum.IsDefined(typeof(T),result)) throw new ArgumentException("Unknown "+typeof(T).Name+": "+value);
            return result;
        }
        public static CombatData Load(string enemies,string towers,string stage,string upgrades,string waves)
        {
            var d=new CombatData();
            foreach(var r in Rows(enemies,9)) { var kind=Kind<EnemyKind>(r[0]); if(d.Enemies.ContainsKey(kind))throw new ArgumentException("Duplicate enemy kind"); d.Enemies.Add(kind,new EnemySpec {Kind=kind,Health=I(r[1]),Speed=F(r[2]),CoreDamage=I(r[3]),Gold=I(r[4]),Defense=F(r[5]),BuffRadius=F(r[6]),BuffSpeed=F(r[7])}); if(r[8]!="provisional")throw new ArgumentException("Unknown balance status"); }
            foreach(var r in Rows(towers,8)) { var kind=Kind<TowerKind>(r[0]);d.Towers.Add(kind,new TowerSpec{Kind=kind,Cost=I(r[1]),Damage=F(r[2]),Rate=F(r[3]),Range=F(r[4]),ProjectileSpeed=F(r[5]),BuffDamage=F(r[6])});if(r[7]!="provisional")throw new ArgumentException("Unknown balance status"); }
            var settings=Rows(stage,2).ToDictionary(r=>r[0],r=>r[1]);
            d.CoreEnergy=I(settings["coreEnergy"]);d.StartGold=I(settings["startGold"]);d.StartCrystals=I(settings["startCrystals"]);d.WaveReward=I(settings["waveReward"]);d.PreparationSeconds=F(settings["preparationSeconds"]);
            foreach(var setting in settings.Where(x=>x.Key.StartsWith("waveReward")&&x.Key!="waveReward"))
            {
                int wave=I(setting.Key.Substring("waveReward".Length));
                if(wave<=0)throw new ArgumentException("Invalid reward wave");
                d.WaveRewards.Add(wave,I(setting.Value));
            }
            d.PlayerFirstCost=I(settings["playerFirstCost"]);d.PlayerSecondIncrease=I(settings["playerSecondIncrease"]);d.PlayerIncreaseStep=I(settings["playerIncreaseStep"]);
            d.DiagnosticStartDistance=F(settings["diagnosticStartDistance"]);d.DiagnosticSpacing=F(settings["diagnosticSpacing"]);d.DiagnosticGold=I(settings["diagnosticGold"]);d.DiagnosticCrystals=I(settings["diagnosticCrystals"]);
            d.Player=new CombatStats{Damage=F(settings["playerDamage"]),Rate=F(settings["playerRate"]),Range=F(settings["playerRange"]),ProjectileSpeed=F(settings["playerProjectileSpeed"])};
            foreach(var r in Rows(upgrades,6)) { var u=new UpgradeSpec{Target=r[1],Stat=r[2],Delta=F(r[3]),Cost=I(r[4]),CostIncrement=I(r[5])}; u.Target=string.Equals(u.Target,"Player",StringComparison.OrdinalIgnoreCase)?"Player":Kind<TowerKind>(u.Target).ToString();if(!new[]{"damage","rate","range","projectileSpeed","buffDamage"}.Contains(u.Stat))throw new ArgumentException("Unknown upgrade stat");if(d.Upgrades.Any(x=>x.Target==u.Target&&x.Stat==u.Stat))throw new ArgumentException("Duplicate target/stat upgrade");d.Upgrades.Add(u); }
            foreach(var r in Rows(waves,6)) { var kind=Kind<EnemyKind>(r[2]);if(!d.Enemies.ContainsKey(kind))throw new ArgumentException("Missing enemy reference");d.Waves.Add(new WaveSpec{Wave=I(r[1]),Kind=kind,Count=I(r[3]),Interval=F(r[4]),Start=F(r[5])}); }
            if(!d.Waves.Any(w=>w.Wave==1)||!new[]{EnemyKind.Attack,EnemyKind.Defense,EnemyKind.Buff}.All(d.Enemies.ContainsKey)||d.Towers.Count!=3||d.CoreEnergy<=0||d.Player.Rate<=0||d.Player.ProjectileSpeed<=0||d.Enemies.Values.Any(x=>x.Health<=0||x.Speed<=0)||d.Towers.Values.Any(x=>x.Kind!=TowerKind.Support&&(x.Rate<=0||x.ProjectileSpeed<=0))||d.Waves.Any(x=>x.Wave<=0||x.Count<=0||x.Interval<=0))throw new ArgumentException("Incomplete or invalid combat data");
            return d;
        }
        public int PlayerUpgradePrice(int step) { if(step<1)throw new ArgumentOutOfRangeException(nameof(step));return checked(PlayerFirstCost+(step-1)*PlayerSecondIncrease+PlayerIncreaseStep*(step-1)*(step-2)/2); }
    }
    public static class CombatRules
    {
        public static int Damage(float damage,float defense) { return Mathf.FloorToInt(Mathf.Max(0,damage*(1-defense/100f))+.5f); }
        public static EnemyState Priority(IEnumerable<EnemyState> enemies) { return enemies.Where(e=>e.Alive).OrderBy(e=>e.Kind==EnemyKind.Defense?0:e.Kind==EnemyKind.Buff?1:2).ThenBy(e=>e.Health).ThenBy(e=>e.PathRemaining).ThenBy(e=>e.Id).FirstOrDefault(); }
    }
    public sealed class EnemyState { public int Id,Health;public EnemyKind Kind;public Vector2 Position;public float PathTravelled,PathRemaining,SlowRemaining;public bool Buffed,Exited;public EnemySpec Spec;public bool Enraged => Kind==EnemyKind.Boss&&Health<=Spec.Health/2f;public float MovementSpeed => Spec.Speed*(Enraged?1.3f:1)*(SlowRemaining>0?.8f:1);public bool Alive {get{return Health>0&&!Exited;}} }
    public sealed class TowerState { public int Id,Spent;public TowerKind Kind;public Vector2Int Position;public CombatStats Stats;internal float Cooldown;internal EnemyState Target;internal bool AcquiredOnce; }
    public sealed class ProjectileState { public int Id;public Vector2 Position;public EnemyState Target;public string Source;public float Damage,Speed; }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace CoreGuardian
{
    public enum AugmentationGrade { Silver, Gold, Platinum }
    public enum AugmentationFamily { Gold, Crystals, Flawless, Player, Towers, Core }
    public sealed class AugmentationCard
    {
        public readonly AugmentationGrade Grade;
        public readonly AugmentationFamily Family;
        public string Id => Grade + "_" + Family;
        public string GradeName => Grade == AugmentationGrade.Silver ? "실버" : Grade == AugmentationGrade.Gold ? "골드" : "플래티넘";
        public string Title => new[] { "골드 보급", "수정 보급", "완벽한 방어", "기술병 전투", "포탑 전투", "코어 증축" }[(int)Family];
        public int Value(int silver, int gold, int platinum) => Grade == AugmentationGrade.Silver ? silver : Grade == AugmentationGrade.Gold ? gold : platinum;
        public string Description {
            get {
                switch (Family) {
                    case AugmentationFamily.Gold: return "즉시 " + Value(100,300,600) + "골드 지급";
                    case AugmentationFamily.Crystals: return "즉시 " + Value(80,240,480) + "수정 지급";
                    case AugmentationFamily.Flawless: return "이후 코어 피해 없이 라운드 완료 시\n" + Value(10,30,60) + "골드 + " + Value(5,15,30) + "수정";
                    case AugmentationFamily.Player: return Grade == AugmentationGrade.Platinum ? "매 공격마다 현재 대상에게\n현재 피해로 투사체 1발 추가" : "기술병 피해 입력값 +" + Value(2,4,0) + (Grade == AugmentationGrade.Gold ? "\n명중 시 1초간 이동속도 20% 감소" : "");
                    case AugmentationFamily.Towers: return "현재·이후 설치하는 모든 공격 포탑\n공격력 버프 +" + Value(10,30,60) + "%\n지원 포탑 버프와 합산";
                    default: return "코어 최대·현재 에너지\n각각 +" + Value(2,6,12);
                }
            }
        }
        public AugmentationCard(AugmentationGrade grade, AugmentationFamily family) { Grade=grade; Family=family; }
    }
    public static class AugmentationDeck
    {
        public static readonly IReadOnlyList<AugmentationCard> Cards = Array.AsReadOnly(
            (from AugmentationGrade grade in Enum.GetValues(typeof(AugmentationGrade))
             from AugmentationFamily family in Enum.GetValues(typeof(AugmentationFamily))
             select new AugmentationCard(grade,family)).ToArray());
        public static AugmentationGrade RollGrade(double roll) {
            if (roll < 0 || roll >= 1 || double.IsNaN(roll)) throw new ArgumentOutOfRangeException(nameof(roll));
            return roll < .70 ? AugmentationGrade.Silver : roll < .95 ? AugmentationGrade.Gold : AugmentationGrade.Platinum;
        }
        public static AugmentationCard[] Draw(Random random, IEnumerable<string> selected)
        {
            var history=new HashSet<string>(selected); var result=new List<AugmentationCard>();
            for (int i=0;i<3;i++) {
                var grade=RollGrade(random.NextDouble());
                var candidates=Cards.Where(c=>c.Grade==grade&&!result.Any(r=>r.Id==c.Id)).ToArray();
                var fresh=candidates.Where(c=>!history.Contains(c.Id)).ToArray();
                if (fresh.Length>0) candidates=fresh;
                result.Add(candidates[random.Next(candidates.Length)]);
            }
            return result.ToArray();
        }
        public static int BestIndex(IReadOnlyList<AugmentationCard> cards) {
            if (cards.Count==0) throw new ArgumentException("No cards");
            int best=0;for(int i=1;i<cards.Count;i++)if(cards[i].Grade>cards[best].Grade)best=i;return best;
        }
    }
    public struct AugmentationGrant { public int Gold, Crystals, Core, PlayerDamage; }
    public sealed class AugmentationEffects
    {
        readonly List<string> selected=new List<string>();
        public IReadOnlyList<string> Selected => selected.AsReadOnly();
        public int ExtraPlayerProjectiles { get; private set; }
        public bool PlayerSlow { get; private set; }
        public int TowerBuffPercent { get; private set; }
        public int FlawlessGold { get; private set; }
        public int FlawlessCrystals { get; private set; }
        public AugmentationGrant Apply(AugmentationCard card) {
            var grant=new AugmentationGrant();selected.Add(card.Id);
            switch(card.Family) {
                case AugmentationFamily.Gold: grant.Gold=card.Value(100,300,600);break;
                case AugmentationFamily.Crystals: grant.Crystals=card.Value(80,240,480);break;
                case AugmentationFamily.Flawless: FlawlessGold+=card.Value(10,30,60);FlawlessCrystals+=card.Value(5,15,30);break;
                case AugmentationFamily.Player: if(card.Grade==AugmentationGrade.Platinum)ExtraPlayerProjectiles++;else{grant.PlayerDamage=card.Value(2,4,0);if(card.Grade==AugmentationGrade.Gold)PlayerSlow=true;}break;
                case AugmentationFamily.Towers: TowerBuffPercent+=card.Value(10,30,60);break;
                case AugmentationFamily.Core: grant.Core=card.Value(2,6,12);break;
            }
            return grant;
        }
    }
}
